$p=$_POST;$get=static function($k,$d='')use($p){return $p[$k]??$d;};$ajax=$get('ajax')==='Y';$back=V::local($get('return','/clients/'));$context=V::local($get('context','/clients/'));$success=$context;$result=[];$message='Сохранено';
