case 'client':$name=V::text($get('name'),150,true);$site=V::text($get('site'),255);if($site!==''){if(strpos($site,'://')===false)$site='https://'.$site;$x=parse_url($site);if(!$x||!in_array(strtolower($x['scheme']??''),['http','https'],true)||empty($x['host'])||isset($x['user'])||isset($x['pass'])||preg_match('/\s/u',$site)||mb_strlen($site)>255)throw new InvalidArgumentException('Некорректный сайт.');}$n=$r->addClient($name,$site,V::text($get('note'),3000),$get('active')==='Y',$u);$success='/clients/detail.php?'.http_build_query(['client'=>$n,'tab'=>'data','month'=>V::month($get('month',date('Y-m')))]);break;
