case 'preset':$r->savePreset($id,V::text($get('name'),100,true),V::text($get('title'),180,true),V::text($get('description'),3000),V::id($get('direction','0'),true),V::durations($get('durations')),$get('group')==='Y',$get('favorite')==='Y',$get('active')==='Y',min(10000,V::id($get('sort','100'),true)),V::choice($get('icon','plain'),['phone','tool','bug','test','plain']));$success='/settings/?tab=templates&month='.V::month($get('month',date('Y-m')));break;
case 'package':$ds=$get('directions',[]);if(!is_array($ds)||count($ds)<1||count($ds)>50)throw new InvalidArgumentException('Выберите 1–50 направлений.');$a=[];foreach($ds as $d)$a[]=V::id($d);$m=V::month($get('month'));$r->savePackage($id,V::id($cid),$m,V::text($get('name'),150,true),V::limit($get('hours')),array_values(array_unique($a)),$get('repeat')==='Y',V::month($get('end'),true),V::choice($get('scope','one'),['one','from']),$u);$success='/clients/detail.php?'.http_build_query(['client'=>$cid,'tab'=>'packages','month'=>$m]);break;
