case 'time':$cid=V::id($cid);$task=V::id($get('task'));$date=V::date($get('date'));$result=['task'=>$task,'entry'=>$r->saveTime($id,$cid,$task,V::id($get('package','0'),true),$date,V::parts($get('hours','0'),$get('minutes','0')),V::text($get('description'),3000),V::text($get('note'),5000),$u,V::token($get('request')))];$success=V::workUrl($cid,substr($date,0,7),$context);break;
case 'task':$m=V::month($get('month'));$n=$r->saveTask($id,V::id($cid),V::text($get('name'),180,true),V::text($get('description'),5000),V::text($get('note'),5000),V::id($get('direction')),V::choice($get('status'),['planned','work','done']),$m,$u);$q=[];parse_str(parse_url($context,PHP_URL_QUERY)??'',$q);try{$show=V::month($q['month']??'');}catch(Throwable $e){$show=$m;}$result=['task'=>$n];$success=V::workUrl($cid,$show,$context);break;
